{
  "situation": "We know that fraud model v2 caused a tenfold rise in refused SIM-replacement requests, that it was rolled back to v1 and a human review queue enabled restoring legit_pass_rate to 1.0 and clearing 18 banking lockouts, and that FIN reports the 'fraud wave' label is unsupported and no DPIA record exists for the v2 change. We do not know whether OpCo has a legal duty to report this incident to TDRA/REG, who owns DPIA for model changes, or how to reach the affected bank_flagged customers.",
  "claims": [
    {
      "type": "action",
      "verb": "preserve_logs",
      "params": {},
      "inject_refs": ["S3-I1", "S3-MSG04"],
      "rationale": {
        "observation": "Fraud model v2 caused a tenfold rise in refused SIM replacements and 18 banking lockouts before rollback.",
        "rule": "UAE PDPL Article 19 requires maintaining a special record of Personal Data processing and security measures.",
        "inference": "Preserving logs is necessary to comply with record-keeping and to support any investigation."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0032",
          "quote": "7. Maintain a special record of Personal Data which is processed on behalf of the Controller, provided that such record includes the data of the Controller, the Processor and the Data Protection Officer"
        }
      ]
    },
    {
      "type": "action",
      "verb": "notify",
      "params": {
        "to": "DPA",
        "content": "No DPIA record for fraud model v2 change; automated refusals affected customers; PDPL requires human review and record-keeping. Please advise on DPIA obligations."
      },
      "inject_refs": ["S3-MSG04"],
      "rationale": {
        "observation": "FIN reports no DPIA record for the fraud model v2 change.",
        "rule": "PDPL Article 19 requires human review of automated processing decisions and a record of processing.",
        "inference": "The DPA should be informed of the missing DPIA and potential non-compliance."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0063",
          "quote": "4. The Controller shall include the human element in reviewing automated processing decisions at the request of the Data Subject."
        },
        {
          "chunk_id": "UAE-PDPL#0032",
          "quote": "7. Maintain a special record of Personal Data which is processed on behalf of the Controller, provided that such record includes the data of the Controller, the Processor and the Data Protection Officer"
        }
      ]
    },
    {
      "type": "share",
      "to": ["REG", "DPA"],
      "inject_refs": ["S3-MSG04"],
      "statement": "FIN notification: fraud model v2 caused tenfold rise in refused SIM replacements; rolled back to v1; review queue enabled; legit_pass_rate 1.0; 18 banking lockouts cleared; 'fraud wave' label unsupported by fraud-volume data; no DPIA record for v2; non-SMS confirmation route for bank_flagged produced no change."
    },
    {
      "type": "obligation",
      "statement": "The Controller shall include the human element in reviewing automated processing decisions at the request of the Data Subject.",
      "inject_refs": ["S3-I1", "S3-MSG04"],
      "rationale": {
        "observation": "Automated refusals of SIM replacements occurred, affecting customers.",
        "rule": "UAE PDPL Article 19 requires human review of automated processing decisions on request.",
        "inference": "OpCo must ensure a human review path is available for affected data subjects."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0063",
          "quote": "4. The Controller shall include the human element in reviewing automated processing decisions at the request of the Data Subject."
        }
      ],
      "deadline_hours": null
    },
    {
      "type": "obligation",
      "statement": "Maintain a special record of Personal Data which is processed on behalf of the Controller, including the data of the Controller, the Processor and the Data Protection Officer.",
      "inject_refs": ["S3-I1", "S3-MSG04"],
      "rationale": {
        "observation": "The fraud model processes personal data (subscriber identifiers) for automated decisions.",
        "rule": "UAE PDPL Article 19 requires a special record of processing.",
        "inference": "OpCo must maintain such a record for the fraud model and its changes."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0032",
          "quote": "7. Maintain a special record of Personal Data which is processed on behalf of the Controller, provided that such record includes the data of the Controller, the Processor and the Data Protection Officer"
        }
      ],
      "deadline_hours": null
    },
    {
      "type": "gap",
      "gap_type": "no_rule",
      "statement": "No explicit requirement in the excerpts for a Data Protection Impact Assessment (DPIA) before deploying a fraud model that makes automated decisions on SIM-replacement refusals.",
      "inject_refs": ["S3-I1", "S3-MSG04"],
      "rationale": {
        "observation": "Fraud model v2 was deployed without a DPIA record, as reported by FIN.",
        "rule": "UAE PDPL provides for human review and record-keeping but no explicit DPIA obligation in the excerpts.",
        "inference": "There is a policy gap: no rule mandating a DPIA prior to model changes affecting automated decisions."
      },
      "evidence": [
        {
          "chunk_id": "UAE-PDPL#0063",
          "quote": "4. The Controller shall include the human element in reviewing automated processing decisions at the request of the Data Subject."
        }
      ],
      "global_examples": []
    },
    {
      "type": "insufficient_evidence",
      "statement": "No excerpt states whether OpCo must report this incident to TDRA/REG or within what time.",
      "inject_refs": ["S3-I1", "S3-MSG04"],
      "evidence": []
    }
  ]
}

{
  "situation": "I know that fraud model v2 (live at 08:00) refused roughly 2,750 legitimate SIM-replacement requests concentrated on prepaid and roaming profiles and caused 18 bank-customer lockouts, and that v2 has since been rolled back to v1 with borderline refusals routed to human review, restoring legit_pass_rate to 1.0 and clearing all banking lockouts, while DPA has ordered unaltered preservation of the v2 records from 08:00 and FIN asks whether refusals are still occurring and what authentication was applied. I do not know OpCo's actual SIM-change authentication method or records, any fraud-volume data supporting the 'fraud wave' label, or any DPIA deadline, because the PDPL Implementing Regulations are not yet issued.",
  "claims": [
    {
      "type": "action",
      "verb": "preserve_logs",
      "params": {},
      "inject_refs": ["S3-MSG08"],
      "rationale": {
        "observation": "DPA (S3-MSG08) requires the v2 change record, decision logs, refusal reasons, the human-review queue entries for the refusal spike and rollback window, and the authentication evidence for each refused SIM replacement to be preserved unaltered from the 08:00 deployment.",
        "rule": "FCC 23-95 requires providers to keep records of SIM change requests and the authentication measures they use (US-FCC-23-95#0118), and preserve_logs is my verb for preserving logs and evidence of an incident.",
        "inference": "Executing preserve_logs now freezes the v2 evidence before any further change to the model, the review queue or the dashboard can overwrite it."
      },
      "evidence": [
        {"chunk_id": "US-FCC-23-95#0118", "quote": "Finally, the Report and Order requires that providers keep records of"}
      ]
    },
    {
      "type": "action",
      "verb": "notify",
      "params": {
        "to": "FIN",
        "content": "NOC to FIN: v2 was rolled back to v1 and borderline refusals were routed to human review; telemetry now shows legit_pass_rate 1.0 and locked_out_banking 0, so no bank customer from the 08:00-to-rollback window remains locked out by an un-reviewed refusal. The v2 refusals were automated, no SIM change was effected for a refused request, and the non-SMS confirmation route offered to the bank_flagged cohort produced no change. NOC holds no record of which authentication method was applied before effecting SIM changes and no authentication log for the refused requests; the v2 change record, refusal reasons and review-queue entries are being preserved unaltered per DPA's instruction."
      },
      "inject_refs": ["S3-MSG11", "S3-FB01", "S3-FB02", "S3-FB03", "S3-I3"],
      "rationale": {
        "observation": "FIN asks whether any SIM-replacement refusals affecting bank customers are still occurring and what authentication was applied before effecting any SIM change.",
        "rule": "Providers are expected to have processes for customer notification and response to failed authentication attempts and to keep authentication records (US-FCC-23-95#0118).",
        "inference": "I can answer the 'still occurring' part from the rollback and review-queue telemetry, but must state plainly that NOC holds no authentication record, and pass that element to insufficient_evidence."
      },
      "evidence": [
        {"chunk_id": "US-FCC-23-95#0118", "quote": "notification and response to failed authentication attempts, institute"}
      ]
    },
    {
      "type": "action",
      "verb": "notify",
      "params": {
        "to": "customers",
        "content": "If your SIM-replacement request was refused on or after 08:00, the refusal came from an automated fraud model that has been withdrawn; borderline refusals are now checked by people, so please re-apply. If you are abroad and cannot receive one-time passwords, use your bank's in-app authentication to approve transactions."
      },
      "inject_refs": ["S3-I3", "S3-I2"],
      "rationale": {
        "observation": "About 2,750 legitimate SIM-replacement requests were refused and the affected users, including customers abroad, cannot receive OTPs and are locked out of banking.",
        "rule": "FCC 23-95 requires providers to develop, maintain and implement procedures for addressing failed authentication attempts in connection with a SIM change request (US-FCC-23-95#0134).",
        "inference": "Telling the affected cohort that the model was withdrawn and that requests are now human-reviewed gives them a route back into service instead of leaving the refusal as final."
      },
      "evidence": [
        {"chunk_id": "US-FCC-23-95#0134", "quote": "(2) Response to failed authentication attempts. A CMRS provider"}
      ]
    },
    {
      "type": "obligation",
      "statement": "From the 08:00 deployment onwards, preserve unaltered the v2 change record, decision logs and refusal reasons, the human-review queue entries for the refusal spike and the rollback window, and the authentication evidence for each refused SIM replacement, and furnish the human-review record and the personal-data record under the PDPL record-keeping duty.",
      "inject_refs": ["S3-MSG08"],
      "rationale": {
        "observation": "DPA (S3-MSG08) imposes the preservation and record duty on OpCo with immediate effect and states the Bureau cannot quote a DPIA deadline because the Implementing Regulations are not yet issued.",
        "rule": "Recordkeeping obligations attach to SIM change requests and the authentication measures in place (US-FCC-23-95#0081).",
        "inference": "The preservation duty is live now, is not contingent on the DPIA deadline, and no end date for it is stated in the inject."
      },
      "evidence": [
        {"chunk_id": "US-FCC-23-95#0081", "quote": "And the requirement that wireless providers keep records of data"}
      ],
      "deadline_hours": null
    },
    {
      "type": "gap",
      "gap_type": "no_deadline",
      "statement": "There is no deadline for the DPIA and personal-data record-keeping triggered by the v2 change: the DPA cannot quote one because the PDPL Implementing Regulations are not yet issued, so the clock for a high-risk automated decision change is undefined.",
      "inject_refs": ["S3-MSG08"],
      "rationale": {
        "observation": "DPA states the Bureau cannot quote a DPIA deadline because the Implementing Regulations are not yet issued, while requiring the personal-data and human-review records now.",
        "rule": "PDPL provides for evaluating a set of similar processing operations and coordinating with the DPO (UAE-PDPL#0069), but the text we hold fixes no deadline or trigger for that evaluation.",
        "inference": "Without a deadline, a change like v2 can be deployed, refuse thousands of requests, be rolled back and preserved, with no date by which a DPIA must exist."
      },
      "evidence": [
        {"chunk_id": "UAE-PDPL#0069", "quote": "4. The Controller may carry out one evaluation of a set of processing operations which hav"}
      ],
      "global_examples": [
        {"chunk_id": "US-FCC-23-95#0134", "quote": "6. Delayed indefinitely, amend Sec. 64.2010 by adding paragraphs"}
      ]
    },
    {
      "type": "gap",
      "gap_type": "no_rule",
      "statement": "No UAE rule in our materials requires secure authentication before a SIM change, periodic review of that authentication, or a human review path for automated refusals; v2 refused about 2,750 legitimate requests with no review path until it was enabled.",
      "inject_refs": ["S3-I3", "S3-I1"],
      "rationale": {
        "observation": "v2 refusals concentrated on prepaid and roaming profiles and there was no human review path for a refused request, while the only UAE text we hold on SIM-change authentication is a 2022 judgment holding a bank and a telecom liable after a SIM was issued without following identification protocol.",
        "rule": "FCC rules require secure authentication before executing a SIM change, regular review of authentication methods, and procedures for failed authentication attempts (US-FCC-23-95#0133, US-FCC-23-95#0134); I hold no equivalent UAE instrument.",
        "inference": "In the UAE material available to me, authentication quality and review of automated refusals are enforced only after the fact through court liability, not ex ante by rule."
      },
      "evidence": [
        {"chunk_id": "UAE-PRESS-SIMSWAP-COURT-2022#0000", "quote": "According to court records, the telecoms service provider issued a new SIM card to fraudsters in March 2019 under the client's registered mobile number without following identification protocol."}
      ],
      "global_examples": [
        {"chunk_id": "US-FCC-23-95#0133", "quote": "confirm the customer's identity before executing a SIM change request,"},
        {"chunk_id": "US-FCC-23-95#0134", "quote": "(2) Response to failed authentication attempts. A CMRS provider"}
      ]
    },
    {
      "type": "gap",
      "gap_type": "overlap",
      "statement": "Ownership of authentication is split between the bank and the operator: the CBUAE-driven shift places authentication integrity on the banks while the SIM credential that carries SMS OTPs is controlled by OpCo's SIM-change process, so customers abroad fall between the two and OpCo's non-SMS confirmation route for the bank_flagged cohort produced no change.",
      "inject_refs": ["S3-I2", "S3-MSG11", "S3-FB03"],
      "rationale": {
        "observation": "The shift to in-app authentication is described as placing responsibility on the banks, while travellers abroad already complained of not receiving SMS OTPs, and OpCo's alternative route for the bank_flagged cohort produced no change.",
        "rule": "US rules place the SIM-change authentication duty on the wireless provider (US-FCC-DA-24-649#0003).",
        "inference": "Each institution holds half of the authentication chain, so a refusal at the operator produces a lockout at the bank with no shared owner for the end-to-end outcome."
      },
      "evidence": [
        {"chunk_id": "UAE-PRESS-CBUAE-OTP-2025#0002", "quote": "This shift also places full responsibility for authentication integrity squarely on the banks themselves,"}
      ],
      "global_examples": [
        {"chunk_id": "US-FCC-DA-24-649#0003", "quote": "Commission revised its Customer Proprietary Network Information (CPNI) and Local Number Portability"}
      ]
    },
    {
      "type": "gap",
      "gap_type": "no_rule",
      "statement": "No rule or standard in our materials governs how an internal fraud indicator may be labelled and shared: the v2 refusal spike was shown as a 'fraud wave' on the fraud dashboard although no fraud-volume data supported it, and the label travelled to FIN and REG.",
      "inject_refs": ["S3-I1", "S3-MSG04", "S3-MSG11", "S3-MSG08"],
      "rationale": {
        "observation": "The refusal spike was labelled a fraud wave without fraud-volume data, that label reached banks and the regulator, and DPA directed that it not be presented as a fraud wave unless supported by fraud-volume data.",
        "rule": "The closest UAE text shows a market changing security practice on an unannounced Central Bank signal (UAE-PRESS-CBUAE-OTP-2025#0000), and FCC expects providers to hold data that lets them measure the effectiveness of their authentication measures (US-FCC-23-95#0081).",
        "inference": "With no substantiation rule, an unsupported fraud label can be generated internally and consumed by counterparties as if it were confirmed."
      },
      "evidence": [
        {"chunk_id": "UAE-PRESS-CBUAE-OTP-2025#0000", "quote": "The Central Bank of the UAE has not officially announced the cancellation of SMS or email OTPs."}
      ],
      "global_examples": [
        {"chunk_id": "US-FCC-23-95#0081", "quote": "need to measure the effectiveness of their customer authentication and"}
      ]
    },
    {
      "type": "share",
      "to": ["FIN", "REG"],
      "inject_refs": ["S3-I2", "S3-MSG11", "S3-FB03"],
      "statement": "Context for the banking lockouts: UAE banks are moving OTP authentication out of SMS/email into mobile-banking apps (Central Bank circular reported by The National; in-app authentication from 25 July 2025), and customers travelling outside the UAE already reported not receiving SMS OTPs or receiving them too late. The locked-out bank customers are therefore also exposed to a structural SMS-OTP problem, not only to OpCo's v2 refusals, and OpCo's non-SMS confirmation route offered to the bank_flagged cohort produced no change."
    },
    {
      "type": "insufficient_evidence",
      "statement": "The question FIN asks (S3-MSG11), what authentication was applied before effecting any SIM change, is not answerable from my material: my inbox and the knowledge set contain only the FCC standard for authenticating a customer before a SIM change, not OpCo's authentication method, any authentication record for the refused requests, or evidence of whether any SIM change was effected without authentication.",
      "inject_refs": ["S3-MSG11"],
      "evidence": [
        {"chunk_id": "US-FCC-23-95#0133", "quote": "methods to authenticate a customer that are reasonably designed to"}
      ]
    }
  ]
}

{
  "situation": "I know that OpCo's fraud model v2, deployed at 08:00, produced a tenfold rise in refused SIM-replacement requests (about 2,750 legitimate refusals since 08:00, concentrated on prepaid and roaming profiles), 18 banking lockouts, and that the model was rolled back to v1 with borderline refusals routed to human review (legit_pass_rate 1.0, lockouts 0); NOC holds no authentication log for the refused requests and no DPIA record for the v2 change, and no human review path exists for a refused request. I do not know whether any refusals are still occurring, what authentication (if any) was applied before each SIM change, whether any real fraud volume justified the 'fraud wave' label, or what DPIA deadline applies, because the PDPL Implementing Regulations are not yet issued.",
  "claims": [
    {
      "type": "action",
      "verb": "open_incident",
      "params": {
        "topic": "OpCo fraud model v2 automated SIM-replacement refusals: 08:00 deployment, ~2,750 legitimate refusals concentrated on prepaid and roaming profiles, 18 banking lockouts, no human review path for a refused request, and no DPIA record or per-refusal authentication evidence"
      },
      "inject_refs": ["S3-I3", "S3-I4", "S3-MSG16"],
      "rationale": {
        "observation": "Automated refusals of SIM replacement have already caused a documented denial of access to banking services, and the customer group (S3-I4) reports no explanation and no appeal route, while NOC holds no authentication record for the refused requests (S3-MSG16).",
        "rule": "UAE courts have treated SIM issuance without following identification protocol and security-system breaches by both a bank and a telecommunications provider as actionable harm, attributing liability to both.",
        "inference": "The operator's automated refusal of SIM-replacement requests is a distinct regulatory matter that warrants its own incident record covering the refusals, the denial of essential services, the absent human review path and the missing DPIA and authentication evidence."
      },
      "evidence": [
        {"chunk_id": "UAE-PRESS-SIMSWAP-COURT-2022#0000", "quote": "The court heard that the client was a victim of SIM swap fraud, which was attributed to breaches in the security systems of both the bank and the telecommunications provider."}
      ]
    },
    {
      "type": "action",
      "verb": "request_report",
      "params": {
        "from": "NOC",
        "topic": "Confirm whether any SIM-replacement refusals affecting bank customers are still occurring; state the authentication method applied before effecting each SIM change since the v2 deployment; describe the explanation and appeal route available to a customer whose request is refused by an automated decision; and state what fraud-volume data, if any, supports the 'fraud wave' label"
      },
      "inject_refs": ["S3-MSG11", "S3-I3", "S3-I4"],
      "rationale": {
        "observation": "REG has asked OpCo to confirm whether refusals affecting bank customers are still occurring and what authentication was applied, and a customer group reports refusals with no explanation and no appeal route.",
        "rule": "Comparable SIM-swap regimes require a clear process for customers to report fraud, prompt investigation and remediation, and documentation of fraud involving their accounts.",
        "inference": "TDRA needs a report from the licensee on the continuing state of refusals, the authentication actually applied, and the customer-facing explanation and appeal route before it can close or escalate the incident."
      },
      "evidence": [
        {"chunk_id": "US-FCC-23-95#0095", "quote": "requiring wireless providers to maintain a clear process for customers to report fraud, promptly investigate and remediate fraud, and promptly provide customers with documentation of fraud involving their accounts"}
      ]
    },
    {
      "type": "action",
      "verb": "request_audit",
      "params": {
        "of": "NOC",
        "topic": "Testing and change records for fraud model v2 (pre-deployment validation, approval and change record), decision logs and refusal reasons for the 08:00 deployment through the rollback window, human-review queue entries for the refusal spike and rollback, and the per-refusal authentication evidence"
      },
      "inject_refs": ["S3-FB01", "S3-MSG08", "S3-MSG09"],
      "rationale": {
        "observation": "The v2 change went live without a DPIA record, and the authentication evidence for each refused SIM replacement is not held by NOC; the Bureau has required the same preservation set that TDRA is aligning to.",
        "rule": "Comparable regimes require wireless providers to use secure methods of authenticating customers before performing SIM changes, to review and update those methods at least annually, and to keep records of SIM change requests and the authentication measures they use.",
        "inference": "TDRA must obtain the licensee's own testing, change and authentication records, because without them neither the safety of the v2 change nor the authentication actually applied can be audited."
      },
      "evidence": [
        {"chunk_id": "US-FCC-23-95#0118", "quote": "it requires that wireless providers use secure methods of authenticating customers prior to performing SIM changes and number ports, and to review and update these authentication methods as needed, but at least annually."},
        {"chunk_id": "US-FCC-23-95#0095", "quote": "the Report and Order requires that providers keep records of SIM change requests and the authentication measures they use."}
      ]
    },
    {
      "type": "action",
      "verb": "issue_direction",
      "params": {
        "to": "NOC",
        "direction": "Operate SIM-replacement authentication only as a documented, multi-factor process and maintain a staffed human-review and appeal path for refused requests, so that legitimate customers — including those roaming abroad who depend on their number for banking authentication — are not left without service; until fraud-volume data supports it, do not present the refusal spike as a 'fraud wave' on any dashboard"
      },
      "inject_refs": ["S3-I1", "S3-I3", "S3-MSG08"],
      "rationale": {
        "observation": "The rollback and review-queue routing restored legit_pass_rate to 1.0 and cleared the 18 lockouts, showing the refusal spike was a control failure rather than a supported fraud event, while NOC holds no authentication log and no human review path existed for refused requests.",
        "rule": "Regulators encourage SMS-based authentication for SIM change only when paired with other secure methods as part of multi-factor authentication, and treat secure authentication, notification and remediation as continuity-critical for customers.",
        "inference": "Directing OpCo on authentication resilience and a human-review path is the proportionate continuity measure pending the report and audit, and the unsupported fraud-wave dashboard label must be corrected."
      },
      "evidence": [
        {"chunk_id": "US-FCC-23-95#0017", "quote": "we strongly encourage wireless providers to use this mechanism only when paired with other secure methods of authentication, i.e., as part of multi-factor authentication (MFA)."}
      ]
    },
    {
      "type": "action",
      "verb": "public_statement",
      "params": {
        "content": "TDRA has opened a regulatory incident record into OpCo's automated refusal of SIM-replacement requests, which left some customers unable to receive authentication messages and locked out of online banking. The refusals have been rolled back, borderline requests now go to human review, and affected customers who were refused without an explanation can complain to OpCo and ask for the refusal to be reviewed by a human."
      },
      "inject_refs": ["S3-I4", "S3-I2", "S3-MSG04"],
      "rationale": {
        "observation": "A customer group complains that automated decisions refused their SIM-replacement requests with no explanation and no way to appeal, and banks report customers abroad locked out of online banking.",
        "rule": "Affected AI subjects should be made aware of the procedures for challenging significant automated decisions, and those procedures should be convenient and user-friendly.",
        "inference": "A short public statement is the appropriate way to tell affected customers that the refusals have been reversed and what challenge route they can use, without asserting an unproven fraud wave."
      },
      "evidence": [
        {"chunk_id": "UAE-AI-ETHICS-2022#0028", "quote": "AI operators should make affected AI subjects aware of these procedures and should design them to be convenient and user-friendly."}
      ]
    },
    {
      "type": "obligation",
      "statement": "Customers affected by the automated SIM-replacement refusals have the right, on request to the controller, to obtain information on decisions made based on automated processing, including the refusal of their SIM replacement, and on how to submit complaints.",
      "inject_refs": ["S3-I4", "S3-MSG06"],
      "rationale": {
        "observation": "Customers refused by the v2 model were given no explanation and no appeal route, and the DPA has flagged the automated refusals as a PDPL matter.",
        "rule": "The PDPL gives the data subject the right, on request to the controller and without consideration, to obtain information on decisions made based on automated processing, including profiling, and on how to submit complaints.",
        "inference": "The controller handling these refusals owes customers information on the automated decision and the complaint route, and TDRA's incident handling must test that this right was and is being given."
      },
      "deadline_hours": null,
      "evidence": [
        {"chunk_id": "UAE-PDPL#0047", "quote": "c. Decisions made based on automated processing, including profiling."},
        {"chunk_id": "UAE-PDPL#0047", "quote": "i. How to submit complaints to the Bureau."}
      ]
    },
    {
      "type": "obligation",
      "statement": "Affected customers must be able to challenge the automated refusal of their SIM-replacement request and, where appropriate, obtain a human review of the decision.",
      "inject_refs": ["S3-I4", "S3-I3"],
      "rationale": {
        "observation": "No human review path exists for a refused request and customers report no way to appeal, so the refusals operated as unchallengeable automated decisions.",
        "rule": "Under the UAE AI Ethics Principles, AI subjects should be able to challenge significant automated decisions concerning them and AI operators should provide procedures for doing so, including human review where appropriate.",
        "inference": "The refusal of a SIM replacement is a significant decision for the affected customer, so a challenge and human-review route is owed before such refusals can be relied on."
      },
      "deadline_hours": null,
      "evidence": [
        {"chunk_id": "UAE-AI-ETHICS-2022#0028", "quote": "AI subjects should be able to challenge significant automated decisions concerning them and, where appropriate, be able to opt out of such decisions"}
      ]
    },
    {
      "type": "gap",
      "gap_type": "no_deadline",
      "statement": "No DPIA-completion, record-keeping or breach-notification deadline can be set or enforced for the fraud model v2 change, because the PDPL Implementing Regulations that would fix those periods have not been issued; the Bureau itself cannot quote a DPIA deadline.",
      "inject_refs": ["S3-MSG08", "S3-MSG18", "S3-MSG06"],
      "rationale": {
